import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionLibrarySmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-library-')),file=path.join(dir,'Portada.svg');
 await fs.writeFile(file,'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="tomato"/><text x="10" y="40">Mi portada</text></svg>');
 try{
  await page.evaluate(()=>{delete project.nwMotionLibrary;project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera de Motion Lab'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function ready(id,text){await page.waitForFunction(({id,text})=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&(!id||d.querySelector('[data-id="'+id+'"]'))&&(!text||d.querySelector('.hd')?.textContent===text);},{},{id,text});}
  async function ids(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>n.dataset.motionLayer));}
  async function choose(id){await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');await ready(id);}
  async function text(id,value){await choose(id);const input=await page.$('[data-motion-content-panel] .nw-motion-content-row:not([hidden]) input[data-motion-content]');await input.click();await page.keyboard.down('Control');await page.keyboard.press('A');await page.keyboard.up('Control');await page.keyboard.type(value);await page.keyboard.press('Tab');await ready(id,value);}
  async function save(name){await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-library-name]');await page.keyboard.type(name);await page.click('[data-motion-library-save]');return page.evaluate(()=>JSON.parse(JSON.stringify(project.nwMotionLibrary.at(-1))));}
  async function openSaved(id){await page.click('[data-motion-saved="'+id+'"]');await ready();return ids();}
  async function pose(id,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({id,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id],n=d.querySelector('[data-id="'+id+'"]');return [0,.2,.8].map(p=>{rt.set(p);return {vars:['x','y','z','rx','ry','scale','rot','opacity','blur'].map(k=>n.style.getPropertyValue('--nw-sd-'+k)),src:n.querySelector('img')?.getAttribute('src')};});},{id,selector,gid});}
  await page.click('.tb-left [data-motion-open]');await ready();const original=await ids();
  await choose(original[0]);const chooser=page.waitForFileChooser();await page.click('[data-motion-upload-open="0"]');await (await chooser).accept([file]);
  await page.waitForFunction(id=>{const lab=document.querySelector('.nw-motion-dialog'),img=lab.querySelector('iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img');return !lab.querySelector('[data-motion-library-save]').disabled&&img?.complete&&img.naturalWidth===300;},{},original[0]);
  await page.$eval('[data-motion-key-property="z"]',n=>{n.value='-500';n.dispatchEvent(new Event('change',{bubbles:true}));});
  await text(original[4],'Mi composición <b>literal</b>');const prepared=await pose(original[0]);
  const saved=await save('<b>Mi portada</b>');assert.equal(saved.elements.length,6);assert.equal(saved.assets.length,3);assert.equal(saved.config.template,'iso-focus');assert.equal(saved.elements[4].text,'Mi composición <b>literal</b>');assert.ok(saved.elements.every(e=>!e.parent));assert.ok(saved.assets.some(a=>a.name==='Portada.svg'&&a.data.startsWith('data:')));
  assert.equal(await page.$eval('[data-motion-saved="'+saved.id+'"] strong',n=>n.textContent),saved.name);assert.equal(await page.$('[data-motion-saved="'+saved.id+'"] strong b'),null);
  assert.deepEqual(await pose(original[0]),prepared,'Saving the library does not alter the current preview');
  assert.equal(await page.evaluate(()=>{const p=JSON.parse(JSON.stringify(project));delete p.nwMotionLibrary;return JSON.stringify(p);}),before.project,'Saving a blueprint does not insert a scene, change outside content or add project assets');assert.equal(await page.evaluate(()=>history.length),1);assert.deepEqual(await page.evaluate(()=>loadProject().nwMotionLibrary),[saved]);
  await page.click('[data-motion-close]');await page.click('.tb-left [data-motion-open]');await ready();
  const copied=await openSaved(saved.id);await ready(copied[4],saved.elements[4].text);assert.ok(copied.every(id=>!original.includes(id)));assert.equal(await page.$eval('[data-motion-config="source"]',n=>n.value),'time');assert.deepEqual(await pose(copied[0]),prepared,'Saved copy preserves actual image and interpolation');
  await text(copied[4],'Solo esta copia');await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await ready(undefined,'Diseño en movimiento.');await openSaved(saved.id);await ready(copied[4],'Solo esta copia');assert.deepEqual(await page.evaluate(()=>project.nwMotionLibrary),[saved],'Editing a reused draft never changes its blueprint');
  await page.click('[data-motion-insert-group]');const first=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),config:g.nwMotionInstance,name:g.name};});assert.equal(first.name,saved.name+' · composición');assert.equal(first.config.template,'iso-focus');assert.equal(first.config.name,saved.name);assert.equal(first.members[4].text,'Solo esta copia');assert.equal(await page.evaluate(()=>sec().sdEnabled),false);assert.deepEqual(await page.evaluate(()=>sec().elements[0]),before.outside);assert.equal(await page.evaluate(()=>project.assets.images.length),before.assets+3);assert.ok(first.members.every(e=>!saved.elements.some(s=>s.id===e.id)));assert.ok(first.members.filter(e=>e.type==='image').every(e=>!saved.assets.some(a=>a.id===e.assetId)));assert.ok(first.members.flatMap(e=>e.sdKeyframes||[]).every(k=>!saved.elements.flatMap(e=>e.sdKeyframes||[]).some(old=>old.id===k.id)));
  await page.click('.tb-left [data-motion-open]');await ready();const secondIds=await openSaved(saved.id);await ready(secondIds[4],saved.elements[4].text);await page.click('[data-motion-insert-group]');const second=await page.evaluate(gid=>{const g=sec().elements.find(e=>e.nwMotionInstance&&e.id!==gid);return {gid:g.id,members:sec().elements.filter(e=>e.parent===g.id)};},first.gid);assert.equal(second.members[4].text,saved.elements[4].text);assert.ok(second.members.every(e=>!first.members.some(old=>old.id===e.id)));assert.deepEqual(await page.evaluate(gid=>sec().elements.filter(e=>e.parent===gid),first.gid),first.members);
  // A library save while editing a placed instance saves a new blueprint, without applying the pending instance changes.
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),first.gid);await ready();await text(first.members[4].id,'Otra versión');const variation=await save('Portada revisada');assert.equal(variation.elements[4].text,'Otra versión');assert.equal(await page.$$eval('[data-motion-template]',ns=>ns.every(n=>n.disabled)),true);await page.click('[data-motion-close]');assert.deepEqual(await page.evaluate(gid=>sec().elements.filter(e=>e.parent===gid),first.gid),first.members);assert.deepEqual(await page.evaluate(()=>project.nwMotionLibrary[0]),saved);
  const beforeRemove=await page.evaluate(()=>JSON.stringify(project));await page.click('.tb-left [data-motion-open]');await ready();await page.click('[data-motion-library-remove="'+saved.id+'"]');assert.deepEqual(await page.evaluate(()=>project.nwMotionLibrary),[variation]);assert.deepEqual(await page.evaluate(gid=>sec().elements.filter(e=>e.parent===gid),first.gid),first.members);await page.click('[data-motion-close]');const removed=await page.evaluate(()=>JSON.stringify(project));await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),beforeRemove);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),removed);await page.evaluate(()=>undo());
  assert.deepEqual(await page.evaluate(()=>migrate(JSON.parse(JSON.stringify(project))).nwMotionLibrary),[saved,variation],'JSON migration retains embedded library data');
  await page.reload({waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.NAGWEB_MOTION_LAB&&project.nwMotionLibrary?.length===2);assert.deepEqual(await page.evaluate(()=>project.nwMotionLibrary),[saved,variation]);await page.click('.tb-left [data-motion-open]');await ready();
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});const compact=await openSaved(saved.id);await ready(compact[4],saved.elements[4].text);assert.equal(await page.$eval('[data-motion-library-remove="'+saved.id+'"]',n=>getComputedStyle(n).display!=='none'),true);assert.ok(await page.$eval('.nw-motion-dialog',n=>n.getBoundingClientRect().right<=innerWidth));await page.click('[data-motion-close]');await page.setViewport(viewport);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='library-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#library-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},first.gid);assert.deepEqual(await pose(first.members[0].id,'#library-export',first.gid),prepared);assert.equal(await page.$eval('#library-export',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').textContent,first.members[4].id),'Solo esta copia');assert.equal(await page.$eval('#library-export',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"] img').naturalWidth,first.members[0].id),300);
  console.log('Biblioteca personal Motion Lab: guardar antes de insertar, texto literal, imágenes incluidas, copias independientes con IDs y momentos propios, borradores, Tiempo sin Director, guardar desde instancia sin aplicarla, quitar/Deshacer/Rehacer, JSON y recarga, pantalla compacta y animación exportada OK');
 }finally{
  await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#library-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});
 }
}
